import {rimebunCaveSlots} from './rimebun.js?v=0.87.0';
import {DATA} from './data.js?v=0.90.40';
import {legalForm} from './route-roster.js?v=0.87.0';
import {SIDE_CONTENT,CAVE_FLOORS,CAVE_MYTHIC,EXPLORATION_QUESTS} from './exploration-data.js?v=0.90.40';
export function explorationState(state){return state.exploration??={claims:[],trades:[],finds:[],quests:[],mythic:null};}
export function grantExplorationReward(state,reward){for(const [key,value]of Object.entries(reward)){if(key==='held'){state.heldItems??={};state.heldItems[value]=(state.heldItems[value]||0)+1;}else state[key]=(state[key]||0)+value;}}
export function claimExplorationCache(state,id){const content=SIDE_CONTENT.find(c=>c.id+'-cache'===id),floor=CAVE_FLOORS.find(f=>f.room+'-cache'===id),q=explorationState(state);if(q.claims.includes(id)||(!content&&!floor))return false;q.claims.push(id);grantExplorationReward(state,content?.reward||floor.reward);return true;}
export function tradeCandidates(state,content){return state.party.concat(state.reserve).filter(u=>u.species.id===content.wanted&&u.hp>0&&!u.dead&&!u.originalStarter&&!u.giftOrigin&&Number.isInteger(u.level)&&u.level>=1);}
export function exchangeAbyssal(state,content,uid,createUnit){const q=explorationState(state);if(q.trades.includes(content.id))return null;const old=tradeCandidates(state,content).find(u=>u.uid===uid);if(!old)return null;const species=DATA.species.find(s=>s.id===content.offered);if(!species||legalForm(species.id,old.level)!==species.id)return null;const incoming=createUnit(species,old.level);if(!incoming||incoming.level!==old.level||!incoming.moves.length)return null;incoming.tradeOrigin=content.name;incoming.originalStarter=false;incoming.lives=1;const group=state.party.includes(old)?state.party:state.reserve;group[group.indexOf(old)]=incoming;if(old.heldItem){state.heldItems??={};state.heldItems[old.heldItem]=(state.heldItems[old.heldItem]||0)+1;}if(state.leadUid===old.uid)state.leadUid=incoming.uid;q.trades.push(content.id);return incoming;}
export function questFinds(state,key){return explorationState(state).finds.filter(id=>id.startsWith('explore-find-'+key+'-')).length;}
export function recordExplorationFind(state,id){if(!/^explore-find-(orchard|relic|cave)-[123]$/.test(id))return false;const q=explorationState(state);if(q.finds.includes(id))return false;q.finds.push(id);return true;}
export function finishExplorationQuest(state,key){const quest=EXPLORATION_QUESTS[key],q=explorationState(state);if(!quest||q.quests.includes(key)||questFinds(state,key)!==3)return false;q.quests.push(key);grantExplorationReward(state,quest.reward);return true;}
export function canMeetMythic(state){const q=explorationState(state);return !q.mythic&&!!(q.huntSeen||q.huntBattlePending);}
export function resolveCaveMythic(state,id,outcome){const q=explorationState(state);if(id!==CAVE_MYTHIC.id||q.mythic||!['captured','defeated'].includes(outcome))return false;q.mythic=outcome;return true;}
export function caveRoute(room){const floor=CAVE_FLOORS.find(f=>f.room===room);if(!floor)return null;return {room,area:{id:room,name:floor.name},explorationTable:true,tables:['DAY','NIGHT'].map(phase=>({id:room+'-'+phase,area_id:room,phase,slots:rimebunCaveSlots(floor).map(s=>({...s,species_id:legalForm(s.species_id,floor.min)}))}))};}
export function installExplorationTrainers(expansion,voices){for(const f of CAVE_FLOORS){if(expansion.trainers.some(t=>t.id===f.trainerId))continue;expansion.trainers.push({id:f.trainerId,name:f.trainerName,runtimeAuthored:true,ai_tier:'Advanced',role:'relic-hunter',team:f.trainer.map((id,i)=>{id=legalForm(id,f.levels[i]);return {slot:i+1,species_id:id,level:f.levels[i],current_form_legal_move_ids:DATA.learnsets.filter(l=>l.species_id===id&&l.level<=f.levels[i]&&DATA.moves.find(m=>m.id===l.move_id)?.category).map(l=>l.move_id)};})});voices[f.trainerId]={before:f.trainerText,after:f.trainerAfter,repeat:f.trainerRepeat};}}
export function explorationJournal(state,room){const c=SIDE_CONTENT.find(c=>c.room===room),f=CAVE_FLOORS.find(f=>f.room===room),q=explorationState(state);if(f)return `${f.name} · Wild levels ${f.min}–${f.max}. Inscriptions ${questFinds(state,'cave')}/3. ${q.mythic?'Waranwei '+q.mythic+'.':f.index===4?'Something is moving in the flooded cistern. Stay close to the ascent stairs.':'Challenge the salvage crew to use the next descent rope.'}`;if(c){const key=Object.keys(EXPLORATION_QUESTS).find(k=>EXPLORATION_QUESTS[k].room===room);return `${c.name} offers a same-level trade. ${q.claims.includes(c.id+'-cache')?'Cache collected.':'A supply cache lies off the trail.'} ${key?EXPLORATION_QUESTS[key].title+' · '+questFinds(state,key)+'/3 found.':''}`;}return null;}
